import sys
import os
import json
import csv
from decimal import Decimal
from datetime import datetime, timedelta

# Decision rules: mapping rule_id -> fact_name -> (document, field, type)
RULES = {
    "lca.wage_105": {
        "offered wage": {"document": "lca_disclosure", "field": "WAGE_RATE_OF_PAY_FROM", "type": "amount"},
        "prevailing wage": {"document": "lca_disclosure", "field": "PREVAILING_WAGE", "type": "amount"},
    },
    "lca.three_years": {
        "begin date": {"document": "lca_disclosure", "field": "BEGIN_DATE", "type": "date"},
        "end date": {"document": "lca_disclosure", "field": "END_DATE", "type": "date"},
    },
}

# Entity identifier column for each document
DOC_ENTITY_COL = {
    "lca_disclosure": "CASE_NUMBER",
}

def excel_serial_to_date(serial):
    """Convert an Excel serial date number to a YYYY-MM-DD string."""
    try:
        s = int(float(serial))
    except (ValueError, TypeError):
        return None
    # Excel epoch: 1899-12-30 (works correctly for serials >= 61)
    base = datetime(1899, 12, 30)
    dt = base + timedelta(days=s)
    return dt.strftime("%Y-%m-%d")

def normalize_value(raw, value_type):
    """Normalize a raw CSV value according to its type. Return None if empty/invalid."""
    if raw is None:
        return None
    s = raw.strip()
    if s == "":
        return None
    if value_type == "amount":
        try:
            d = Decimal(s)
            if d == d.to_integral_value():
                return str(int(d))
            return str(d)
        except Exception:
            return None
    elif value_type == "date":
        # Try Excel serial first
        date_str = excel_serial_to_date(s)
        if date_str:
            return date_str
        # Try common date string formats
        for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%d-%b-%Y", "%Y/%m/%d"):
            try:
                dt = datetime.strptime(s, fmt)
                return dt.strftime("%Y-%m-%d")
            except Exception:
                continue
        return None
    else:
        return s

def load_document(packet_dir, document, cache):
    """Load a CSV document and group rows by entity. Return dict entity -> list of rows."""
    if document in cache:
        return cache[document]
    file_path = os.path.join(packet_dir, document + ".csv")
    rows_by_entity = {}
    if os.path.exists(file_path):
        with open(file_path, newline='', encoding='utf-8-sig') as f:
            reader = csv.DictReader(f)
            if reader.fieldnames:
                reader.fieldnames = [name.strip() for name in reader.fieldnames]
            entity_col = DOC_ENTITY_COL.get(document, "CASE_NUMBER")
            for row in reader:
                entity = row.get(entity_col, "").strip()
                if entity:
                    rows_by_entity.setdefault(entity, []).append(row)
    cache[document] = rows_by_entity
    return rows_by_entity

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>", file=sys.stderr)
        sys.exit(1)
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    pairs = manifest.get("pairs", [])
    facts_by_rule = manifest.get("facts", {})

    doc_cache = {}
    output = {}

    for pair in pairs:
        if "::" not in pair:
            output[pair] = {}
            continue
        rule_id, entity = pair.split("::", 1)
        facts = facts_by_rule.get(rule_id, [])
        result = {}
        for fact in facts:
            if rule_id not in RULES or fact not in RULES[rule_id]:
                result[fact] = "ABSENT"
                continue
            rule_info = RULES[rule_id][fact]
            document = rule_info["document"]
            field = rule_info["field"]
            value_type = rule_info["type"]

            rows_by_entity = load_document(packet_dir, document, doc_cache)
            rows = rows_by_entity.get(entity, [])

            values = []
            for row in rows:
                raw = row.get(field, "")
                norm = normalize_value(raw, value_type)
                if norm is not None:
                    values.append(norm)

            if not values:
                result[fact] = "ABSENT"
            elif len(set(values)) == 1:
                result[fact] = [values[0], document]
            else:
                result[fact] = "CONFLICT"
        output[pair] = result

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()

