import sys
import os
import json
import csv
from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation
from collections import defaultdict

def excel_serial_to_date(serial_str):
    """Convert an Excel serial date to a YYYY-MM-DD string."""
    try:
        serial = float(serial_str)
    except (ValueError, TypeError):
        return None
    if serial < 1:
        return None
    if serial.is_integer():
        serial = int(serial)
    # Excel serial date conversion (accounts for the 1900 leap-year bug)
    if serial < 60:
        date = datetime(1899, 12, 31) + timedelta(days=serial - 1)
    elif serial == 60:
        # Excel 1900-02-29, which does not exist in the Gregorian calendar
        return None
    else:
        date = datetime(1899, 12, 30) + timedelta(days=serial)
    return date.strftime('%Y-%m-%d')

def normalize_value(fact, value):
    """Normalize a value for conflict comparison based on the fact type."""
    if fact in ('offered wage', 'prevailing wage'):
        try:
            return Decimal(value)
        except (InvalidOperation, ValueError):
            return value
    elif fact in ('begin date', 'end date'):
        return excel_serial_to_date(value)
    else:
        return value

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>", file=sys.stderr)
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    # The decision rules establish that all facts come from lca_disclosure.csv
    csv_path = os.path.join(packet_dir, 'lca_disclosure.csv')
    document_name = os.path.splitext(os.path.basename(csv_path))[0]

    records_by_case = defaultdict(list)
    if os.path.exists(csv_path):
        with open(csv_path, 'r', newline='', encoding='utf-8-sig') as f:
            reader = csv.DictReader(f)
            for row in reader:
                case = row.get('CASE_NUMBER', '').strip()
                if case:
                    records_by_case[case].append(row)

    # Mapping from fact name to the CSV column that establishes it (per decision rules)
    fact_to_column = {
        'offered wage': 'WAGE_RATE_OF_PAY_FROM',
        'prevailing wage': 'PREVAILING_WAGE',
        'begin date': 'BEGIN_DATE',
        'end date': 'END_DATE',
    }

    output = {}
    for pair in manifest['pairs']:
        rule_id, entity = pair.split('::', 1)
        facts = manifest['facts'].get(rule_id, [])
        result = {}
        for fact in facts:
            col = fact_to_column.get(fact)
            if not col:
                result[fact] = "ABSENT"
                continue

            rows = records_by_case.get(entity, [])
            non_empty_values = []
            for row in rows:
                val = row.get(col, '')
                if val is not None and val.strip() != '':
                    non_empty_values.append(val.strip())

            if not non_empty_values:
                result[fact] = "ABSENT"
            else:
                normalized = [normalize_value(fact, v) for v in non_empty_values]
                if all(n is not None for n in normalized) and len(set(normalized)) == 1:
                    if fact in ('offered wage', 'prevailing wage'):
                        result[fact] = [str(normalized[0]), document_name]
                    elif fact in ('begin date', 'end date'):
                        result[fact] = [normalized[0], document_name]
                    else:
                        result[fact] = [non_empty_values[0], document_name]
                else:
                    # Fallback to raw string comparison if normalization fails
                    if len(set(non_empty_values)) == 1:
                        result[fact] = [non_empty_values[0], document_name]
                    else:
                        result[fact] = "CONFLICT"
        output[pair] = result

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()

